from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether
from pathlib import Path

out=Path('output/pdf/fyxnora-role-workflow.pdf');out.parent.mkdir(parents=True,exist_ok=True)
styles=getSampleStyleSheet();navy=colors.HexColor('#172B4D');blue=colors.HexColor('#167ED2');teal=colors.HexColor('#08A28F');light=colors.HexColor('#F4F7FB');muted=colors.HexColor('#667085')
styles.add(ParagraphStyle(name='TitleX',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=28,leading=33,textColor=navy,spaceAfter=12))
styles.add(ParagraphStyle(name='SubX',parent=styles['BodyText'],fontSize=11,leading=17,textColor=muted,spaceAfter=16))
styles.add(ParagraphStyle(name='H1X',parent=styles['Heading1'],fontSize=20,leading=24,textColor=navy,spaceBefore=8,spaceAfter=11))
styles.add(ParagraphStyle(name='H2X',parent=styles['Heading2'],fontSize=13,leading=17,textColor=blue,spaceBefore=8,spaceAfter=7))
styles.add(ParagraphStyle(name='BodyX',parent=styles['BodyText'],fontSize=9.5,leading=14,textColor=navy,spaceAfter=7))
styles.add(ParagraphStyle(name='SmallX',parent=styles['BodyText'],fontSize=8,leading=11,textColor=muted))
styles.add(ParagraphStyle(name='CenterX',parent=styles['BodyText'],fontSize=9,leading=13,alignment=TA_CENTER,textColor=navy))

def header_footer(canvas,doc):
    canvas.saveState();canvas.setFillColor(blue);canvas.rect(0,A4[1]-12*mm,A4[0],12*mm,fill=1,stroke=0);canvas.setFillColor(colors.white);canvas.setFont('Helvetica-Bold',9);canvas.drawString(18*mm,A4[1]-8*mm,'FYXNORA  |  ROLE WORKFLOW & EMAIL OPERATIONS')
    canvas.setFillColor(muted);canvas.setFont('Helvetica',8);canvas.drawString(18*mm,10*mm,'Prepared 11 October 2026');canvas.drawRightString(A4[0]-18*mm,10*mm,f'Page {doc.page}');canvas.restoreState()

doc=SimpleDocTemplate(str(out),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=22*mm,bottomMargin=18*mm,title='Fyxnora Role Workflow')
story=[Spacer(1,8*mm),Paragraph('Fyxnora Role Workflow',styles['TitleX']),Paragraph('Operational guide for customer, technician, service-centre, regional and super-admin experiences, including verified email delivery.',styles['SubX'])]
summary=[[Paragraph('<b>Test repair</b><br/>FX-2026-001001',styles['CenterX']),Paragraph('<b>Final state</b><br/>CLOSED',styles['CenterX']),Paragraph('<b>Approved quote</b><br/>INR 4,200',styles['CenterX']),Paragraph('<b>Timeline</b><br/>17 events',styles['CenterX'])]]
t=Table(summary,colWidths=[42*mm]*4,rowHeights=23*mm);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),light),('BOX',(0,0),(-1,-1),.6,colors.HexColor('#DDE5EF')),('INNERGRID',(0,0),(-1,-1),.4,colors.HexColor('#DDE5EF')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7)]));story += [t,Spacer(1,7*mm),Paragraph('1. Role-based experiences',styles['H1X'])]
roles=[('Customer','Register with email OTP; book repairs; view estimate and timeline; approve quotation; track delivery; close repair; use warranty and support records.'),('Field technician / pickup partner','Accept assigned visits; schedule pickup; record condition and OTP custody; move devices in transit; perform verified delivery handover.'),('Service-centre partner','Receive devices; diagnose; submit itemized quotations; manage repair and parts; complete quality checks; assign linked technicians; view centre commission.'),('City / regional operations','Oversee assigned regional work; manage coverage; coordinate verified providers; monitor service progress, exceptions and escalations.'),('Super admin','Manage users and roles; reset passwords; maintain catalogue and pricing; configure centre commission; review queries; configure SMTP and recipients.')]
data=[[Paragraph('<b>Portal</b>',styles['SmallX']),Paragraph('<b>Responsibilities</b>',styles['SmallX'])]]+[[Paragraph(f'<b>{a}</b>',styles['BodyX']),Paragraph(b,styles['BodyX'])] for a,b in roles]
t=Table(data,colWidths=[45*mm,123*mm],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),blue),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#DDE5EF')),('BACKGROUND',(0,1),(-1,-1),colors.white),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));story += [t,PageBreak(),Paragraph('2. End-to-end repair workflow',styles['H1X'])]
steps=[('1. Booking','Customer selects category, brand, model and repairs; the platform calculates the estimate and creates a BOOKED order.'),('2. Operations assignment','Super admin assigns regional operations and a verified service centre. The service centre assigns a linked technician.'),('3. Pickup and custody','Technician schedules the visit, records condition details, verifies pickup OTP and moves the sealed device in transit.'),('4. Diagnosis and quotation','Service centre receives the device, records diagnosis and sends an itemized quotation. Customer approves or rejects it.'),('5. Repair and QC','Approved work moves through repair, parts handling and quality control before it is marked ready for delivery.'),('6. Delivery and closure','Technician verifies delivery handover. Customer confirms completion and closes the order.')]
for title,body in steps: story.append(KeepTogether([Paragraph(title,styles['H2X']),Paragraph(body,styles['BodyX'])]))
story += [Spacer(1,4*mm),Paragraph('Verified status path',styles['H2X']),Paragraph('BOOKED -> ASSIGNED -> VISIT_SCHEDULED -> PICKUP_VERIFIED -> IN_TRANSIT -> RECEIVED_AT_CENTRE -> DIAGNOSIS -> QUOTE_SENT -> CUSTOMER_APPROVED -> REPAIRING -> QUALITY_CHECK -> READY_FOR_DELIVERY -> OUT_FOR_DELIVERY -> DELIVERED -> CLOSED',styles['SmallX']),Spacer(1,7*mm),Paragraph('3. Email verification and notifications',styles['H1X'])]
email_rows=[('Registration OTP','Six-digit code sent to the entered email; expires after 10 minutes; maximum five incorrect attempts.'),('Welcome','Sent after OTP validation and confirmed account creation.'),('Repair milestones','Customer receives booking and every subsequent state transition. Internal recipients receive each request.'),('Business enquiries','Confirmation goes to the enquirer and the full enquiry goes to configured internal recipients.'),('Global CC','All automated messages include the comma-separated CC addresses configured by super admin.'),('SMTP test','Admin sends a real test message to the saved test recipient.')]
data=[[Paragraph('<b>Event</b>',styles['SmallX']),Paragraph('<b>Email behaviour</b>',styles['SmallX'])]]+[[Paragraph(f'<b>{a}</b>',styles['BodyX']),Paragraph(b,styles['BodyX'])] for a,b in email_rows]
t=Table(data,colWidths=[43*mm,125*mm],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#DDE5EF')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));story += [t,PageBreak(),Paragraph('4. SMTP setup guide',styles['H1X']),Paragraph('Configure this in Super Admin -> Integrations / Email SMTP.',styles['BodyX'])]
providers=[('Gmail','smtp.gmail.com','587','No (STARTTLS)','Use a Google app password; normal account passwords are usually rejected.'),('Zoho Mail India','smtp.zoho.in','465','Yes','Use the Zoho mailbox or app-specific password. Global accounts may use smtp.zoho.com.'),('Other / Custom','Provider supplied','465 or 587','Provider supplied','Enter any standards-compatible SMTP host, port and credential.')]
data=[[Paragraph(f'<b>{x}</b>',styles['SmallX']) for x in ['Provider','Host','Port','Implicit TLS','Notes']]]+[[Paragraph(x,styles['SmallX']) for x in row] for row in providers]
t=Table(data,colWidths=[28*mm,37*mm,15*mm,24*mm,64*mm],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),blue),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#DDE5EF')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));story += [t,Spacer(1,7*mm),Paragraph('Recipient controls',styles['H2X']),Paragraph('<b>Internal notification recipients:</b> comma-separated operations/support addresses that must receive new accounts, bookings and enquiries.<br/><b>CC recipients:</b> comma-separated oversight addresses copied on every automated message.<br/><b>Test recipient:</b> destination used by the Send test email action.',styles['BodyX']),Paragraph('5. Validation and launch checklist',styles['H1X'])]
checks=['Run the unified schema so email_verification_codes exists.','Set SMTP_SETTINGS_ENCRYPTION_KEY to a strong value of at least 32 characters.','Save SMTP provider credentials and send a real test email.','Register a new customer and verify the OTP, welcome email and login.','Create a repair and advance one status to confirm customer, internal and CC delivery.','Review spam, SPF, DKIM and DMARC configuration for the sender domain before production.','Replace all published test-account passwords before launch.']
for item in checks: story.append(Paragraph(f'&#10003;&nbsp;&nbsp;{item}',styles['BodyX']))
story += [Spacer(1,8*mm),Paragraph('Security note',styles['H2X']),Paragraph('SMTP passwords are encrypted at rest. OTP codes are stored only as SHA-256 hashes, are single-use, expire after ten minutes and are limited to five failed verification attempts. Customer passwords are never stored in the verification table.',styles['BodyX'])]
doc.build(story,onFirstPage=header_footer,onLaterPages=header_footer)
print(out)
